import{_ as r,a0 as p,w as m,s as a,ao as s,I as e,x as o,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何用 Gonimo 創建一個免費的嬰兒監視系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 Gonimo 創建一個免費的嬰兒監視系統 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 Gonimo 創建一個免費的嬰兒監視系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 Gonimo 創建一個免費的嬰兒監視系統 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20170928 How to create a free baby monitoring system with Gonimo","title":"如何用 Gonimo 創建一個免費的嬰兒監視系統","tag":"201901","desc":""},"relativePath":"201901/20170928 How to create a free baby monitoring system with Gonimo.md","filePath":"[post].md"}'),u={name:"201901/20170928 How to create a free baby monitoring system with Gonimo.md"};function d(f,t,b,g,T,C){const i=p("Link");return m(),a("div",null,[t[25]||(t[25]=s('<h1 id="如何用-gonimo-創建一個免費的嬰兒監視系統" tabindex="-1">如何用 Gonimo 創建一個免費的嬰兒監視系統 <a class="header-anchor" href="#如何用-gonimo-創建一個免費的嬰兒監視系統" aria-label="Permalink to “如何用 Gonimo 創建一個免費的嬰兒監視系統”">​</a></h1><blockquote><p>當你可以用兩個設備、瀏覽器和網絡連接就能免費搭建一個嬰兒監視器時，誰還會花錢去買呢？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/baby.png?itok=7jyDs9vE" alt=""></p><p>新父母和準父母很快就會知道將會有一個既長且昂貴的新生兒所需設備的清單，清單中的首位是一個嬰兒監視器，藉此他們可以在做其他事情時照看自己的嬰兒，但這兒有一件不必消耗你的嬰兒經費的設備，Gonimo 是一個可以將現有的設備轉換成嬰兒監控系統的自由開源解決方案，附近大型嬰兒用品商店的過道中有數以千計的其他必備或時尚物品，就可以為其中某一個騰出一些嬰兒的預算。</p><p>Gonimo 誕生時，它的開發者，一個有雙胞胎的開源粉絲，發現現有選擇存在問題：</p><ul><li>現有硬件嬰兒監視器價格昂貴，使用範圍有限，需要您帶着額外的設備。</li><li>雖然有移動監控應用程序，但大多數現有的 iOS / Android 嬰兒監控應用程序都不可靠且不安全，不太容易找到開源產品。</li><li>如果您有兩個小孩（例如雙胞胎），您將需要兩台監視器，使您的成本翻倍。</li></ul><p>Gonimo 是作為一個解決典型的監視器的缺點的開源解決方案而創建的：</p><ul><li>昂貴？不，它是免費的！</li><li>使用範圍有限？不，它適用於互聯網 / WiFi，無論您身在何處。</li><li>下載並安裝應用程序？噢不，它適用於您現有的網絡瀏覽器。</li><li>購買新設備？不用，你可以使用任何筆記本電腦、手機或平板電腦與網絡瀏覽器和麥克風和/或相機。</li></ul><p>（注意：遺憾的是，Apple iOS 設備尚不支持，但預計很快就會發生變化 —— 請繼續閲讀，瞭解如何幫實現這一目標。）</p><h3 id="開始" tabindex="-1">開始 <a class="header-anchor" href="#開始" aria-label="Permalink to “開始”">​</a></h3>',10)),e("p",null,[t[1]||(t[1]=o("將您的設備轉換為嬰兒監視器很容易。從您設備的瀏覽器（理想情況下為 Chrome），訪問 ",-1)),n(i,{href:"https://gonimo.com/"},{default:l(()=>[...t[0]||(t[0]=[o("gonimo.com",-1)])]),_:1}),t[2]||(t[2]=o(" 並單擊 “Start baby monitor” 以訪問該 Web 應用程序。",-1))]),t[26]||(t[26]=e("p",null,"1、創建家庭：在首次啓動的屏幕上，你會看到一隻可愛的兔子在地球上奔跑。這是您創建新家庭的地方。單擊 “+” 按鈕並接受隨機生成的姓氏或鍵入您自己的選擇。",-1)),t[27]||(t[27]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/u128651/start-screen.png",alt:"Start screen",title:"Start screen"})],-1)),t[28]||(t[28]=e("p",null,[e("em",null,"從開始屏幕創建一個新家庭")],-1)),t[29]||(t[29]=e("p",null,"2、邀請設備：建立完家庭以後，下個屏幕將指示您邀請其他設備加入你的 Gonimo 家庭。您可以通過電子郵件直接發送一次性邀請鏈接，也可以將其複製並粘貼到消息中。對其他設備，只需打開該鏈接並接受邀請。對您要邀請的任何其他設備重複此過程。您的設備現在屬於同一家庭，可以作為一個完全正常工作的嬰兒監視器系統進行配合。",-1)),t[30]||(t[30]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/u128651/invite-screen.png",alt:"Invite screen",title:"Invite screen"})],-1)),t[31]||(t[31]=e("p",null,[e("em",null,"邀請家庭成員")],-1)),e("p",null,[t[4]||(t[4]=o("3、啓動嬰兒站流：接下來，通過轉到 ",-1)),n(i,{href:"https://app.gonimo.com/"},{default:l(()=>[...t[3]||(t[3]=[o("Gonimo 主屏",-1)])]),_:1}),t[5]||(t[5]=o("，點擊帶有奶嘴的按鈕，並允許網絡瀏覽器訪問設備的麥克風和攝像頭，選擇將嬰兒的音頻和視頻流式傳輸到父母的設備。調整相機以指向寶寶的牀，或關閉它以節省設備電池（音頻仍將流式傳輸）。點擊“Start”。該流現在處於活動狀態。",-1))]),t[32]||(t[32]=s('<p><img src="https://opensource.com/sites/default/files/u128651/baby-select.png" alt="Select baby station" title="Select baby station"></p><p><em>選擇嬰兒站</em></p><p><img src="https://opensource.com/sites/default/files/u128651/baby-screen.png" alt="Press Start" title="Press Start"></p><p><em>按“Start”開始以流式傳輸視頻</em></p><p>4、連接到父母站流：要查看嬰兒站流，請轉到 Gonimo 家族中的另外的設備 —— 即父母站。點擊 Gonimo 主屏幕上的 “Parent” 按鈕。您將看到該系列中所有設備的列表；旁邊有一個閃動的“Connect”按鈕的是活躍的嬰兒站。選擇“Connect”，您可以通過點對點音頻/視頻流看到和聽到您的寶寶。音量條為傳輸的音頻流提供可視化。</p><p><img src="https://opensource.com/sites/default/files/u128651/parent-select.png" alt="Select parent station" title="Select parent station"></p><p><em>選擇父母站</em></p><p><img src="https://opensource.com/sites/default/files/u128651/parent-screen.png" alt="Press Connect" title="Press Connect"></p><p><em>按下“Connect”開始觀看嬰兒流。</em></p><p>5、恭喜！您已成功將設備直接通過網絡瀏覽器轉換為嬰兒監視器，無需下載或安裝任何應用程序！</p>',10)),e("p",null,[t[7]||(t[7]=o("有關重命名設備，從系列中刪除設備或刪除系列的詳細信息和詳細説明，請查看 gonimo.com 的",-1)),n(i,{href:"https://gonimo.com/index.php#intro"},{default:l(()=>[...t[6]||(t[6]=[o("視頻教程",-1)])]),_:1}),t[8]||(t[8]=o("。",-1))]),t[33]||(t[33]=s('<h3 id="家庭系統的靈活性" tabindex="-1">家庭系統的靈活性 <a class="header-anchor" href="#家庭系統的靈活性" aria-label="Permalink to “家庭系統的靈活性”">​</a></h3><p>Gonimo 的優勢之一是其基於家庭的系統，它為即使在商業 Android 或 iOS 應用中也無法提供的各種情況提供了極大的靈活性。要深入瞭解這些功能，我們假設您創建了一個由三個設備組成的家庭系統。</p><ul><li>多嬰兒：如果你想留意你在兩個不同房間睡覺的兩個小孩怎麼辦？在每個孩子的房間放一個設備，並將其設置為嬰兒站。第三個設備將充當父母站，您可以在其上連接到兩個流並通過分屏查看您的幼兒。您甚至可以通過向該家庭系統提供更多設備，並將其設置為嬰兒站來將此用例擴展到兩個以上的嬰兒站。只要您的父母站連接到第一個嬰兒站，請單擊左上角的後退箭頭返回“設備概述”屏幕。現在您可以連接到第二個（以及依次為第三個、第四個、第五個和第五個等）設備，並自動建立分屏。酷！</li><li>多父母：如果爸爸想在他上班的時候看孩子怎麼辦？只需邀請第四個設備（例如，他的辦公室 PC ）到家庭並將其設置為父母站。父母雙方都可以通過他們自己的設備同時檢查他們的孩子，甚至可以獨立地選擇他們希望連接的孩子。</li><li>多家庭：單個設備也可以是幾個家庭系統的一部分。當您的嬰兒站與您一起時，如平板電腦，您經常訪問親戚或朋友時，這非常有用。為“奶奶的房子”或“約翰叔叔的房子”創建另一個家庭，其中包括您的嬰兒站設備與奶奶或約翰叔叔的設備配對。您可以隨時通過嬰兒站設備的 Gonimo 主屏幕在這些家庭中切換嬰兒站設備。</li></ul><h3 id="想要參加嗎" tabindex="-1">想要參加嗎？ <a class="header-anchor" href="#想要參加嗎" aria-label="Permalink to “想要參加嗎？”">​</a></h3><p>Gonimo 團隊喜歡開源。代碼來自社區，代碼用於社區。Gonimo 的用户對我們非常重要，但它們只是 Gonimo 故事的一部分。幕後有創意的大腦是創造出色嬰兒監視器體驗的關鍵。</p><p>目前我們特別需要那些願意成為 iOS 11 測試者的人的幫助，因為 Apple 在 iOS 11 中對 WebRTC 的支持意味着我們最終將能夠支持 iOS 設備。如果可以，請幫助我們實現這個令人讚歎的里程碑。</p>',6)),e("p",null,[t[10]||(t[10]=o("如果您瞭解 Haskell 或想要了解它，您可以查看 ",-1)),n(i,{href:"https://github.com/gonimo/gonimo"},{default:l(()=>[...t[9]||(t[9]=[o("GitHub 上我們的代碼",-1)])]),_:1}),t[11]||(t[11]=o("。歡迎發起拉取請求、審查代碼以及提出問題。",-1))]),t[34]||(t[34]=e("p",null,"最後，請通過向新父母和開源世界宣傳 Gonimo 嬰兒監視器是易於使用並且便攜的。",-1)),t[35]||(t[35]=e("h3",{id:"關於作者",tabindex:"-1"},[o("關於作者 "),e("a",{class:"header-anchor",href:"#關於作者","aria-label":"Permalink to “關於作者”"},"​")],-1)),t[36]||(t[36]=e("p",null,"Robert Klotzner：我是雙胞胎的父親，一個程序員。當我聽到普通人可以給計算機編程時，我買了一本 1200 頁的關於 C++ 的書開始學習，我當時才十五歲。我堅持用 C++ 相當長的一段時間，學習了 Java 又迴歸到 C++，學習了 D、Python 等等，最終學習了 Haskell。我喜歡 Haskell 是因為它豐富的類型系統，這幾乎可以避免我書寫錯誤的代碼。強壯的靜態類型和性能讓我愛上了 C++……",-1)),t[37]||(t[37]=e("hr",null,null,-1)),e("p",null,[t[13]||(t[13]=o("via: ",-1)),n(i,{href:"https://opensource.com/article/17/9/gonimo"},{default:l(()=>[...t[12]||(t[12]=[o("https://opensource.com/article/17/9/gonimo",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=o("作者：",-1)),n(i,{href:"https://opensource.com/users/robert-klotzner"},{default:l(()=>[...t[14]||(t[14]=[o("Robert Klotzner",-1)])]),_:1}),t[18]||(t[18]=o(" 譯者：",-1)),n(i,{href:"https://github.com/lintaov587"},{default:l(()=>[...t[15]||(t[15]=[o("lintaov587",-1)])]),_:1}),t[19]||(t[19]=o(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[16]||(t[16]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=o("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[20]||(t[20]=[o("LCTT",-1)])]),_:1}),t[23]||(t[23]=o(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...t[21]||(t[21]=[o("Linux中國",-1)])]),_:1}),t[24]||(t[24]=o(" 榮譽推出",-1))])])}const x=r(u,[["render",d]]);export{P as __pageData,x as default};
